/**
 * Gate C milestones C1 and C2 of the node-to-predicate projection ExecPlan
 * ({@code .agent/node-predicate-projection-execplan.md}): the two compiler nodes for a variable predicate compile,
 * produce exactly the right rows, read a node's predicate row in bounded chunks, keep nested enumerations apart, and —
 * the correctness heart of the milestone — never skip a predicate whose run cannot be resolved.
 *
 * <p>
 * Everything here runs the <em>real</em> generated Java: each test builds an IR tree, compiles it through the Janino
 * service, and binds a hand-written fixture view. That matters because the claims being made are claims about emitted
 * source. "The generated code contains no branch that skips a predicate with a bad run handle" cannot be checked by
 * reading the IR; it can only be checked by giving the compiled kernel a bad handle and observing what it does with it.
 */
class LmdbNativeNodePredicateKernelTest {

	private static String previousEnabled;

	@BeforeAll
	static void enableCodegen() {
		previousEnabled = System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, "true");
	}

	@AfterAll
	static void restoreCodegenFlag() {
		if (previousEnabled == null) {
			System.clearProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY);
		} else {
			System.setProperty(LmdbNativeJaninoCodegen.ENABLED_PROPERTY, previousEnabled);
		}
	}

	/**
	 * Node 1 has predicates 10 and 20; node 2 has predicate 10 only. Run contents are chosen so a row can be identified
	 * from its values alone.
	 */
	private static FixtureNodePredicates fixture() {
		FixtureNodePredicates view = new FixtureNodePredicates();
		view.add(1, 10, new long[] { 101, 102 });
		view.add(1, 20, new long[] { 201 });
		view.add(2, 10, new long[] { 111 });
		return view;
	}

	// ------------------------------------------------------------------
	// C2: the two nodes emit correct code
	// ------------------------------------------------------------------

	@Test
	void enumeratePredicatesEmitsEveryPredicateOfTheNodeWithItsWholeRun() throws Exception {
		Kernel ir = new Kernel(2,
				List.of(new EnumeratePredicates(0, Operand.constant(0), 0, 1)), emit(0, 1));
		assertRows(run(ir, fixture(), null, 1L),
				new long[][] { { 10, 101 }, { 10, 102 }, { 20, 201 } });
	}

	@Test
	void enumeratePredicatesOfAnAbsentNodeEmitsNothing() throws Exception {
		Kernel ir = new Kernel(2,
				List.of(new EnumeratePredicates(0, Operand.constant(0), 0, 1)), emit(0, 1));
		assertRows(run(ir, fixture(), null, 99L), new long[0][]);
	}

	@Test
	void probeVariableExpandsTheRunOfOneRuntimePredicate() throws Exception {
		Kernel ir = new Kernel(1,
				List.of(new ProbeVariable(0, Operand.constant(0), Operand.constant(1), 0)), emit(0));
		assertRows(run(ir, null, fixture(), 1L, 10L), new long[][] { { 101 }, { 102 } });
		assertRows(run(ir, null, fixture(), 1L, 30L), new long[0][]);
	}

	/**
	 * The row is read in bounded chunks, never as one array the size of the row. A node wide enough to need three
	 * chunks proves both halves of that: every predicate still comes out, and no single copy asked for more than the
	 * fixed chunk width.
	 */
	@Test
	void aWideRowIsReadInBoundedChunksAndStillYieldsEveryPredicate() throws Exception {
		FixtureNodePredicates view = new FixtureNodePredicates();
		int predicates = 150;
		long[][] expected = new long[predicates][];
		for (int i = 0; i < predicates; i++) {
			long predicate = 1000 + i;
			view.add(7, predicate, new long[] { 500_000 + i });
			expected[i] = new long[] { predicate, 500_000 + i };
		}
		Kernel ir = new Kernel(2,
				List.of(new EnumeratePredicates(0, Operand.constant(0), 0, 1)), emit(0, 1));
		assertRows(run(ir, view, null, 7L), expected);

		assertTrue(view.copyRowCalls.size() > 1,
				"a 150-predicate row must take more than one copyRow call, or the chunking is not being exercised");
		int widest = view.copyRowCalls.stream().mapToInt(call -> call.length).max().orElse(0);
		assertTrue(widest <= 64,
				"copyRow asked for " + widest + " predicates at once; the row must be read in bounded chunks so a"
						+ " pathological node cannot force a large uncharged allocation inside every parallel worker");
		assertEquals(predicates, view.copyRowCalls.stream().mapToInt(call -> call.copied).sum());
	}

	/**
	 * Two enumerations in one pipeline share one view but must not share scratch. If the buffers were per view rather
	 * than per node, the inner enumeration would overwrite the predicates the outer one has not processed yet, and the
	 * outer loop would silently produce only its first chunk's worth of rows.
	 */
	@Test
	void nestedEnumerationsDoNotShareTheirScratchBuffers() throws Exception {
		// outer: predicates of node 1 -> (p0, x1); inner: predicates of the far endpoint reached, if any.
		FixtureNodePredicates view = new FixtureNodePredicates();
		view.add(1, 10, new long[] { 2 });
		view.add(1, 20, new long[] { 2 });
		view.add(1, 30, new long[] { 2 });
		view.add(2, 40, new long[] { 401 });
		view.add(2, 50, new long[] { 501 });
		Kernel ir = new Kernel(4, List.of(
				new EnumeratePredicates(0, Operand.constant(0), 0, 1),
				new EnumeratePredicates(0, Operand.col(1), 2, 3)), emit(0, 1, 2, 3));
		assertRows(run(ir, view, null, 1L), new long[][] {
				{ 10, 2, 40, 401 }, { 10, 2, 50, 501 },
				{ 20, 2, 40, 401 }, { 20, 2, 50, 501 },
				{ 30, 2, 40, 401 }, { 30, 2, 50, 501 } });
	}

	/** Two enumerating nodes must not collide in the kernel cache either, or one shape would run the other's code. */
	@Test
	void theTwoNodesContributeDistinctCacheKeys() {
		String enumerate = new Kernel(2,
				List.of(new EnumeratePredicates(0, Operand.constant(0), 0, 1)), emit(0, 1)).shapeKey();
		String probe = new Kernel(2,
				List.of(new ProbeVariable(0, Operand.constant(0), Operand.constant(1), 1)), emit(0, 1)).shapeKey();
		assertTrue(enumerate.contains("EP(n0,"), "enumeration key was " + enumerate);
		assertTrue(probe.contains("PV(d0,"), "probe key was " + probe);
		assertTrue(!enumerate.equals(probe));
	}

	// ------------------------------------------------------------------
	// C1: total resolution, proven by fault injection
	// ------------------------------------------------------------------

	/**
	 * The contract is that {@code copyRow} raises rather than handing back a predicate with no run. When it does, the
	 * kernel must fail: rows have already been emitted, so re-running the shape from the disk trees would duplicate
	 * them, and quietly stopping would report a prefix of the answer as the whole answer.
	 */
	@Test
	void aPredicateWithNoRunFailsTheKernelRatherThanUnderReporting() {
		FixtureNodePredicates view = fixture();
		view.raiseOnPredicate = 20;
		Kernel ir = new Kernel(2,
				List.of(new EnumeratePredicates(0, Operand.constant(0), 0, 1)), emit(0, 1));
		IllegalStateException failure = assertThrows(IllegalStateException.class,
				() -> run(ir, view, null, 1L));
		assertTrue(failure.getMessage().contains("no authoritative run"), failure.getMessage());
	}

	/**
	 * The stronger half of the same claim, aimed at the generated source rather than at the fixture: given a
	 * non-positive run handle — which a correct implementation never returns, but a future buggy one might — the kernel
	 * must <em>not</em> contain a branch that skips it. A skip would turn structural corruption into a silently
	 * incomplete answer, which is precisely the failure the plan forbids. The fixture proves there is no such branch by
	 * observing that the handle is used rather than filtered out.
	 */
	@Test
	void generatedCodeHasNoBranchThatSkipsAnUnresolvableRun() {
		FixtureNodePredicates view = fixture();
		view.poisonRunHandleOfPredicate = 20;
		Kernel ir = new Kernel(2,
				List.of(new EnumeratePredicates(0, Operand.constant(0), 0, 1)), emit(0, 1));
		assertThrows(IllegalStateException.class, () -> run(ir, view, null, 1L));
		assertTrue(view.sizeCalledWithPoisonedHandle,
				"the kernel skipped a predicate whose run handle was not positive instead of using it; that branch"
						+ " would convert corruption into a short answer");
	}

	// ------------------------------------------------------------------

	private static Emit emit(int... cols) {
		return new Emit(cols, false, OutputMods.none());
	}

	private static List<long[]> run(Kernel ir, FixtureNodePredicates nodePredicates,
			FixtureNodePredicates dynamic, long... constants) throws Exception {
		JaninoKernel kernel = LmdbNativeJaninoCodegen.kernel(ir.shapeKey(), ir.className(),
				() -> LmdbNativeKernelEmitter.emit(ir), Long.MAX_VALUE);
		if (kernel == null) {
			kernel = LmdbNativeJaninoCodegen.awaitKernel(ir.shapeKey(), 30, TimeUnit.SECONDS);
		}
		assertNotNull(kernel, "kernel did not compile; source:\n" + LmdbNativeKernelEmitter.emit(ir));
		try {
			kernel.bind(new KernelContext(new NativeLmdbQuerySource.NativeAdjacency[0], constants, new long[0],
					new long[0][], null, null, new org.eclipse.rdf4j.sail.lmdb.evaluation.codegen.KernelPlan[0], 16,
					nodePredicates == null ? new NativeLmdbQuerySource.NodePredicates[0]
							: new NativeLmdbQuerySource.NodePredicates[] { nodePredicates },
					dynamic == null ? new NativeLmdbQuerySource.DynamicAdjacency[0]
							: new NativeLmdbQuerySource.DynamicAdjacency[] { dynamic }));
			int stride = ir.stride();
			long[] buffer = new long[stride * 64];
			List<long[]> rows = new ArrayList<>();
			int filled;
			while ((filled = kernel.fill(buffer, 64)) > 0) {
				for (int r = 0; r < filled; r++) {
					rows.add(Arrays.copyOfRange(buffer, r * stride, (r + 1) * stride));
				}
			}
			return rows;
		} finally {
			kernel.close();
		}
	}

	private static void assertRows(List<long[]> actual, long[][] expected) {
		assertEquals(expected.length, actual.size(),
				"row count; actual rows were " + actual.stream().map(Arrays::toString).toList());
		for (int i = 0; i < expected.length; i++) {
			assertEquals(Arrays.toString(expected[i]), Arrays.toString(actual.get(i)), "row " + i);
		}
	}

	/**
	 * A hand-built stand-in for the store's node-predicate and dynamic views, holding rows in insertion order and
	 * handing out run handles that encode which run they name. It records every {@code copyRow} call so the chunking
	 * discipline can be asserted, and can be told to misbehave in the two ways the total-resolution contract exists to
	 * catch.
	 */
	private static final class FixtureNodePredicates
			implements NativeLmdbQuerySource.NodePredicates, NativeLmdbQuerySource.DynamicAdjacency {

		private record Call(long fromOffset, int length, int copied) {
		}

		private final Map<Long, List<long[]>> rows = new LinkedHashMap<>();
		private final List<long[]> runs = new ArrayList<>();
		private final List<Call> copyRowCalls = new ArrayList<>();

		/** Predicate whose {@code copyRow} raises, imitating a projection that names an absent authoritative row. */
		private long raiseOnPredicate = Long.MIN_VALUE;
		/** Predicate handed back with a non-positive run handle, imitating a hypothetical future bug. */
		private long poisonRunHandleOfPredicate = Long.MIN_VALUE;
		private boolean sizeCalledWithPoisonedHandle;

		void add(long node, long predicate, long[] neighbors) {
			runs.add(neighbors);
			// Handles are 1-based so zero stays available as "absent", matching the store's own convention.
			rows.computeIfAbsent(node, key -> new ArrayList<>()).add(new long[] { predicate, runs.size() });
		}

		@Override
		public long find(long node) {
			List<long[]> row = rows.get(node);
			return row == null ? NativeLmdbQuerySource.NodePredicates.NOT_FOUND : node;
		}

		@Override
		public long rowSize(long rowHandle) {
			return rows.get(rowHandle).size();
		}

		@Override
		public int copyRow(long node, long rowHandle, long fromOffset, int length, long[] predicateTarget,
				int predicateOffset, long[] runTarget, int runOffset) {
			List<long[]> row = rows.get(rowHandle);
			int copied = (int) Math.min(length, row.size() - fromOffset);
			copyRowCalls.add(new Call(fromOffset, length, copied));
			for (int i = 0; i < copied; i++) {
				long[] entry = row.get((int) fromOffset + i);
				if (entry[0] == raiseOnPredicate) {
					throw new IllegalStateException("node-predicate row lists a predicate with no authoritative run: "
							+ node + "/" + entry[0]);
				}
				predicateTarget[predicateOffset + i] = entry[0];
				runTarget[runOffset + i] = entry[0] == poisonRunHandleOfPredicate ? -1L : entry[1];
			}
			return copied;
		}

		@Override
		public long runFor(long node, long rawPredicate) {
			List<long[]> row = rows.get(node);
			if (row == null) {
				return NativeLmdbQuerySource.DynamicAdjacency.NOT_FOUND;
			}
			for (long[] entry : row) {
				if (entry[0] == rawPredicate) {
					return entry[1];
				}
			}
			return NativeLmdbQuerySource.DynamicAdjacency.NOT_FOUND;
		}

		@Override
		public long size(long runHandle) {
			if (runHandle <= 0) {
				sizeCalledWithPoisonedHandle = true;
				throw new IllegalStateException("run handle " + runHandle + " was used rather than skipped");
			}
			return runs.get((int) runHandle - 1).length;
		}

		@Override
		public long neighborAt(long runHandle, long runOffset) {
			return runs.get((int) runHandle - 1)[(int) runOffset];
		}

		@Override
		public long contextAt(long runHandle, long runOffset) {
			return 0L;
		}

		@Override
		public int copyNeighbors(long runHandle, long runOffset, int length, long[] target, int targetOffset) {
			long[] run = runs.get((int) runHandle - 1);
			int copied = (int) Math.min(length, run.length - runOffset);
			for (int i = 0; i < copied; i++) {
				target[targetOffset + i] = run[(int) runOffset + i];
			}
			return Math.max(copied, 0);
		}

		@Override
		public int copyContexts(long runHandle, long runOffset, int length, long[] target, int targetOffset) {
			long[] run = runs.get((int) runHandle - 1);
			int copied = (int) Math.min(length, run.length - runOffset);
			Arrays.fill(target, targetOffset, targetOffset + Math.max(copied, 0), 0L);
			return Math.max(copied, 0);
		}

		@Override
		public boolean runsNeighborOrdered() {
			return true;
		}
	}
}
